def spearman_rho(x, y):
    n = len(x)
    rank_x = {x[i]: i + 1 for i in range(n)}
    rank_y = {y[i]: i + 1 for i in range(n)}

    sum_d_squared = sum((rank_x[xi] - rank_y[yi]) ** 2 for xi, yi in zip(x, y))

    rho = 1 - (6 * sum_d_squared) / (n * (n**2 - 1))
    return rho, None
